-- 워크플로우 항목(workflows_bworkflow_process.classification, CONT_WORK_*)과 항목별 선택값.
-- 값이 하위 선택지를 가지면 enum_values.child_set_id 로 그 선택지 세트를 가리킨다 (항목 -> 선택값, 더 깊어져도 같은 방식).
alter table enum_values add column child_set_id bigint references enum_sets (id);
create index idx_enum_values_child_set on enum_values (child_set_id);

